// Sum over a wavefront (LX_WARP lanes: 32 on RDNA, 64 on CDNA), every lane gets the result.
__device__ __forceinline__ float warp_sum(float v) {
  for (int o = LX_WARP / 2; o > 0; o >>= 1) v += __shfl_xor_sync(LX_FULL_MASK, v, o);
  return v;
}
